{
  "justification": "Issue salience is dominated by economic and service concerns, and the instrument does not capture directional preferences, so placement should stay near the midpoint. Still, the culturally coded items bearing on this axis skew toward TAN themes (immigration, law and order, defence, morality) and outweigh explicitly GAL-coded themes (environment, disarmament), so I assign a modest TAN tilt.",
  "poles": [
    {
      "pole": "tan",
      "basis": "Race relations/Immigration/Immigrants; Crime/Law and order/Violence/Vandalism; Defence/Foreign affairs/International terrorism; Morality/Individual behaviour; Common Market/EU/Europe/Single European Currency",
      "weight": 0.6
    },
    {
      "pole": "gal",
      "basis": "Pollution/Environment; Nuclear weapons/Disarmament",
      "weight": 0.4
    }
  ]
}
